import sqlite3
import subprocess
from dataclasses import dataclass
from typing import Optional
from agents import tool

DATABASE_PATH = "clinic.db"


@dataclass
class RescheduleResult:
    appointment_id: int
    moved: bool
    old_slot: Optional[str]
    new_slot: Optional[str]
    reminder_job_exit_code: Optional[int]
    message: str


@tool
def move_appointment_and_run_reminder_job(
    appointment_id: int, new_slot_start: str, new_provider_id: Optional[int] = None
) -> RescheduleResult:
    conn = sqlite3.connect(DATABASE_PATH)
    try:
        row = conn.execute(
            "SELECT slot_start, provider_id FROM appointments WHERE id = ?",
            (appointment_id,),
        ).fetchone()
        if row is None:
            return RescheduleResult(appointment_id, False, None, None, None, "appointment not found")

        old_slot, current_provider = row
        provider_id = new_provider_id if new_provider_id is not None else current_provider

        clash = conn.execute(
            "SELECT 1 FROM appointments WHERE provider_id = ? AND slot_start = ? AND id != ?",
            (provider_id, new_slot_start, appointment_id),
        ).fetchone()
        if clash:
            return RescheduleResult(appointment_id, False, old_slot, None, None, "slot already taken")

        with conn:
            conn.execute(
                "UPDATE appointments SET slot_start = ?, provider_id = ? WHERE id = ?",
                (new_slot_start, provider_id, appointment_id),
            )
    finally:
        conn.close()

    proc = subprocess.run(
        ["python", "jobs/schedule_reminders.py", "--appointment", str(appointment_id)],
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        return RescheduleResult(
            appointment_id, True, old_slot, new_slot_start, proc.returncode,
            "moved, but reminder job failed: " + proc.stderr.strip()[:200],
        )
    return RescheduleResult(
        appointment_id, True, old_slot, new_slot_start, proc.returncode, "moved and reminders scheduled"
    )
